public class DOMNodePointer_getLanguage_TriageGen0Test {

    /**
     * Helper method to access the protected method getLanguage() via reflection
     */
    private String invokeGetLanguage(DOMNodePointer pointer) throws Exception {
        Method method = DOMNodePointer.class.getDeclaredMethod("getLanguage");
        method.setAccessible(true);
        return (String) method.invoke(pointer);
    }

    @Test
    public void testGetLanguage_ReturnsAttrFromCurrentNode() throws Exception {
        Node mockNode = mock(Element.class);
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(mockNode.getAttribute("xml:lang")).thenReturn("en");

        DOMNodePointer pointer = new DOMNodePointer(mockNode, Locale.ENGLISH);

        assertEquals("en", invokeGetLanguage(pointer));
    }

    @Test
    public void testGetLanguage_ReturnsAttrFromParentNode() throws Exception {
        Node parentNode = mock(Element.class);
        when(parentNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parentNode.getAttribute("xml:lang")).thenReturn("fr");
        when(parentNode.getParentNode()).thenReturn(null);

        Node childNode = mock(Node.class);
        when(childNode.getNodeType()).thenReturn(Node.TEXT_NODE); // Not an element
        when(childNode.getParentNode()).thenReturn(parentNode);

        DOMNodePointer pointer = new DOMNodePointer(childNode, Locale.FRENCH);

        assertEquals("fr", invokeGetLanguage(pointer));
    }

    @Test
    public void testGetLanguage_ReturnsAttrFromGrandparentNode() throws Exception {
        Node grandParent = mock(Element.class);
        when(grandParent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(grandParent.getAttribute("xml:lang")).thenReturn("de");
        when(grandParent.getParentNode()).thenReturn(null);

        Node parent = mock(Element.class);
        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("xml:lang")).thenReturn(""); // Empty string, should continue
        when(parent.getParentNode()).thenReturn(grandParent);

        Node child = mock(Node.class);
        when(child.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(child.getAttribute("xml:lang")).thenReturn(null); // Null, should continue
        when(child.getParentNode()).thenReturn(parent);

        DOMNodePointer pointer = new DOMNodePointer(child, Locale.GERMAN);

        assertEquals("de", invokeGetLanguage(pointer));
    }

    @Test
    public void testGetLanguage_ReturnsNullWhenNoAttrFoundInHierarchy() throws Exception {
        Node node = mock(Element.class);
        when(node.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(node.getAttribute("xml:lang")).thenReturn("");
        when(node.getParentNode()).thenReturn(null);

        DOMNodePointer pointer = new DOMNodePointer(node, Locale.US);

        assertNull(invokeGetLanguage(pointer));
    }

    @Test
    public void testGetLanguage_ReturnsNullWhenNodeIsNull() throws Exception {
        // Passing null to constructor to simulate node being null
        DOMNodePointer pointer = new DOMNodePointer(null, Locale.US);

        assertNull(invokeGetLanguage(pointer));
    }

    @Test
    public void testGetLanguage_SkipsNonElementNodes() throws Exception {
        Node textNode = mock(Node.class);
        when(textNode.getNodeType()).thenReturn(Node.TEXT_NODE);

        Node elementNode = mock(Element.class);
        when(elementNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(elementNode.getAttribute("xml:lang")).thenReturn("es");
        when(elementNode.getParentNode()).thenReturn(null);

        when(textNode.getParentNode()).thenReturn(elementNode);

        DOMNodePointer pointer = new DOMNodePointer(textNode, Locale.forLanguageTag("es"));

        assertEquals("es", invokeGetLanguage(pointer));
    }
}
